      "chunk_id": "text_1",
      "quote": "Point-of-care ultrasound improves clinical outcomes in patients with acute onset dyspnea: a systematic review and meta-analysis",
      "reason": "The title explicitly includes the phrase \"a systematic review and meta-analysis\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Point-of-care ultrasound improves clinical outcomes in patients with acute onset dyspnea: a systematic review and meta-analysis",
      "reason": "The title identifies the intervention (Point-of-care ultrasound) and the population (patients with acute onset dyspnea)."
